func downloadAll(_ urls: [URL], maxConcurrent: Int = 6) async throws -> [URL: Data] {
    try await withThrowingTaskGroup(of: (URL, Data).self) { group in
        var results: [URL: Data] = [:]
        var iterator = urls.makeIterator()

        for _ in 0..<maxConcurrent {                 // start the first 6
            guard let url = iterator.next() else { break }
            group.addTask { (url, try await fetch(url)) }
        }
        while let (url, data) = try await group.next() {
            results[url] = data
            if let next = iterator.next() {          // one finished, add one
                group.addTask { (next, try await fetch(next)) }
            }
        }
        return results
    }
}
